arguments.command:
cd /workspace/task/scratch && md5sum report.md && python3 - <<'EOF'
import re
src=open('report.md',encoding='utf-8').read()
lines=src.split('\n')
start=None
for i,l in enumerate(lines):
    if l.strip()=='## 风险':
        start=i+1;break
if start is None: raise SystemExit('no section')
end=len(lines)
for j in range(start,len(lines)):
    if re.match(r'^##\s',lines[j]):
        end=j;break
body='\n'.join(lines[start:end]).strip()
open('risk.txt','w',encoding='utf-8',newline='\n').write(body)
print(repr(body))
EOF
md5sum report.md; cat risk.txt
